// Call the target function to get a const, read-only C string pointer
const char *p = duix_version();

// The API does not document null returns; bail out if null to avoid UB
if (!p) { FUZZ_BAIL(); }

// Verify there is a null-terminator within a reasonable bound to avoid scanning unbounded memory
size_t len = 0;
for (; len < 2048; ++len) { if (p[len] == '\0') break; }
if (len == 2048) { FUZZ_BAIL(); }

// Do not modify or free the returned pointer; treat it as read-only/static
// To return something to the object pool, allocate a small holder for the pointer itself
const char **version_out = (const char**)malloc(sizeof(const char*));
if (!version_out) { FUZZ_BAIL(); }
*version_out = p;

// Track useful metadata for downstream stubs
FUZZ_SET_ATTR_INT(version_out, "strlen", (int)len);
FUZZ_SET_ATTR_INT(version_out, "readonly", 1);
// Note: We intentionally do not copy or free p; ownership is not transferred by the API.

// Validation: Stub enforces non-null return and bounded null-termination, preserves const/ownership, and exports a stable const char** handle.
